class LRUCache {
public:
    int cap;
    unordered_map<int,Node*> cache;
    Node *head, *tail;
    LRUCache(int capacity):cap(capacity) {
        head = new Node();
        tail = new Node();
        head->next = tail;
        tail->prev = head;
    }
    void removeNode(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    void addToFront(Node* node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }
    int get(int key) {
        if (cache.find(key) == cache.end()) return -1;
        Node* node = cache[key];
        removeNode(node);
        addToFront(node);
        return node->val;
    }
    void put(int key, int value) {
        if (cap == 0) return;
        if (cache.find(key) != cache.end()) {
            Node* node = cache[key];
            node->val = value;
            removeNode(node);
            addToFront(node);
        } else {
            if ((int)cache.size() >= cap) {
                Node* lru = tail->prev;
                removeNode(lru);
                cache.erase(lru->key);
                delete lru;
            }
            Node* node = new Node(key, value);
            cache[key] = node;
            addToFront(node);
        }
    }
};

